import{_ as e,o as l,c as s,af as a}from"./chunks/framework.BSym9njW.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"zh/01-deploy/gemma4/fastflowlm-npu-results.md","filePath":"zh/01-deploy/gemma4/fastflowlm-npu-results.md","lastUpdated":1789547203000}'),i={name:"zh/01-deploy/gemma4/fastflowlm-npu-results.md"};function n(d,t,r,o,g,h){return l(),s("div",null,[...t[0]||(t[0]=[a('<h2 id="fastflowlm-npu-运行结果-gemma-4-e4b" tabindex="-1">FastFlowLM NPU 运行结果：Gemma 4 E4B <a class="header-anchor" href="#fastflowlm-npu-运行结果-gemma-4-e4b" aria-label="Permalink to &quot;FastFlowLM NPU 运行结果：Gemma 4 E4B&quot;">​</a></h2><p>本页数字来自 <strong>2026-09-16</strong> 在 GMKtec EVO-X2（Ryzen AI MAX+ 395 / XDNA2）上的实测。运行时 FastFlowLM <strong>1.0.5</strong>，<code>--pmode performance</code>。部署步骤见 <a href="./fastflowlm-npu-deploy">FastFlowLM 部署</a>。</p><p>对照官方 <a href="https://fastflowlm.com/docs/benchmarks/gemma4_results/" target="_blank" rel="noreferrer">Gemma 4 NPU 基准</a>（Kraken Point / 32 GB，FLM 0.9.40）。原始表：<a href="./assets/bench_gemma4-it_e4b_20260916.csv">bench CSV</a>。</p><hr><h3 id="环境" tabindex="-1">环境 <a class="header-anchor" href="#环境" aria-label="Permalink to &quot;环境&quot;">​</a></h3><p>NPU <code>/dev/accel/accel0</code>，固件 <strong>1.1.2.65</strong>，memlock unlimited。本地已装 <code>gemma4-it:e4b</code>。</p><hr><h3 id="服务跑通-openai-兼容-8219" tabindex="-1">服务跑通（OpenAI 兼容 8219） <a class="header-anchor" href="#服务跑通-openai-兼容-8219" aria-label="Permalink to &quot;服务跑通（OpenAI 兼容 8219）&quot;">​</a></h3><p>短问「只回答一个词：ok」返回 <code>ok</code>。</p><table tabindex="0"><thead><tr><th style="text-align:left;">项</th><th style="text-align:left;">值</th></tr></thead><tbody><tr><td style="text-align:left;">客户端时延</td><td style="text-align:left;">1.52 s</td></tr><tr><td style="text-align:left;">TTFT</td><td style="text-align:left;">1.35 s</td></tr><tr><td style="text-align:left;">进程 RSS</td><td style="text-align:left;"><strong>9275 MiB（约 9.06 GiB）</strong></td></tr></tbody></table><p>视觉探测（红圆 + 蓝矩形）判定正确，说明 <code>vision_weight.q4nx</code> 已加载。</p><hr><h3 id="_1k–32k-阶梯-flm-bench" tabindex="-1">1k–32k 阶梯（<code>flm bench</code>） <a class="header-anchor" href="#_1k–32k-阶梯-flm-bench" aria-label="Permalink to &quot;1k–32k 阶梯（`flm bench`）&quot;">​</a></h3><p>停掉 <code>flm serve</code> 后：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">unset</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ROCM_PATH</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> HIP_PATH</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> LD_LIBRARY_PATH</span></span>\n<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">flm</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> bench</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> gemma4-it:e4b</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --bench-iterations</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;"> 2</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --pmode</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> performance</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>本机 2 次迭代结果：</p><table tabindex="0"><thead><tr><th style="text-align:left;">上下文</th><th style="text-align:right;">TTFT (s)</th><th style="text-align:right;">Prefill (tok/s)</th><th style="text-align:right;">Decode (tok/s)</th><th style="text-align:right;">官方 Kraken decode</th><th style="text-align:right;">官方 Kraken prefill</th></tr></thead><tbody><tr><td style="text-align:left;">1k</td><td style="text-align:right;">2.176 ± 0.005</td><td style="text-align:right;">449.5 ± 1.1</td><td style="text-align:right;"><strong>11.75 ± 0.02</strong></td><td style="text-align:right;">12.6</td><td style="text-align:right;">441</td></tr><tr><td style="text-align:left;">2k</td><td style="text-align:right;">3.479 ± 0.001</td><td style="text-align:right;">559.7 ± 0.1</td><td style="text-align:right;"><strong>11.38 ± 0.03</strong></td><td style="text-align:right;">12.3</td><td style="text-align:right;">572</td></tr><tr><td style="text-align:left;">4k</td><td style="text-align:right;">6.175 ± 0.023</td><td style="text-align:right;">629.1 ± 2.4</td><td style="text-align:right;"><strong>10.94 ± 0.00</strong></td><td style="text-align:right;">11.6</td><td style="text-align:right;">668</td></tr><tr><td style="text-align:left;">8k</td><td style="text-align:right;">11.685 ± 0.030</td><td style="text-align:right;">664.0 ± 1.7</td><td style="text-align:right;"><strong>9.95 ± 0.02</strong></td><td style="text-align:right;">10.6</td><td style="text-align:right;">720</td></tr><tr><td style="text-align:left;">16k</td><td style="text-align:right;">24.293 ± 0.030</td><td style="text-align:right;">638.3 ± 0.8</td><td style="text-align:right;"><strong>8.54 ± 0.01</strong></td><td style="text-align:right;">9.0</td><td style="text-align:right;">695</td></tr><tr><td style="text-align:left;">32k</td><td style="text-align:right;">56.764 ± 0.175</td><td style="text-align:right;">546.1 ± 1.7</td><td style="text-align:right;"><strong>6.61 ± 0.01</strong></td><td style="text-align:right;">6.8</td><td style="text-align:right;">586</td></tr></tbody></table><p><strong>怎么读：</strong></p><ol><li><strong>Decode 全阶梯贴着官方 Kraken，略低 3–7%。</strong> 1k 为 11.75 vs 12.6；32k 为 6.61 vs 6.8。曲线形状一样：上下文越长越慢。Halo 没有数量级优势。</li><li><strong>Prefill 1k 与官方几乎重合（450 vs 441），中段偏低。</strong> 峰值在 8k（664 vs 官方 720），32k 掉到 546（官方 586）。</li><li><strong>TTFT 近似随长度线性变长。</strong> 1k≈2.2 s，32k≈56.8 s。<code>--prefill-chunk-len</code> 默认 4096。</li><li><strong>API 短问 decode 约 12.5 tok/s 高于 bench@1k 的 11.75。</strong> 短问 KV 几乎为空；bench@1k 是先灌 1k 再 decode。比 decode 请用这条阶梯。</li><li><strong>短问算出来的 prefill 无效。</strong> 那是几十个 token 上的固定开销，不是稳态带宽。</li></ol><hr><h3 id="并发-serve-模式" tabindex="-1">并发（serve 模式） <a class="header-anchor" href="#并发-serve-模式" aria-label="Permalink to &quot;并发（serve 模式）&quot;">​</a></h3><p>短问 <code>ok</code>，并发 1 / 2 / 4，全部成功、无 503：</p><table tabindex="0"><thead><tr><th style="text-align:left;">并发</th><th style="text-align:left;">成功</th><th style="text-align:left;">整波墙钟</th><th style="text-align:left;">平均时延</th><th style="text-align:left;">最大时延</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">1/1</td><td style="text-align:left;">1.39 s</td><td style="text-align:left;">1.39 s</td><td style="text-align:left;">1.39 s</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">2/2</td><td style="text-align:left;">3.12 s</td><td style="text-align:left;">2.42 s</td><td style="text-align:left;">3.12 s</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">4/4</td><td style="text-align:left;">6.64 s</td><td style="text-align:left;">4.27 s</td><td style="text-align:left;">6.63 s</td></tr></tbody></table><p>墙钟约 <strong>1× / 2.2× / 4.8×</strong>。NPU 一次只跑一路，其余进 <code>--q-len</code> 队列。</p><hr><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><ul><li>部署路径：<code>flm pull</code> → <code>flm serve</code> → <code>/v1/chat/completions</code>。</li><li>文本、视觉都通；常驻约 <strong>9 GiB</strong>。</li><li>1k–32k decode <strong>11.75 → 6.61 tok/s</strong>，与官方 Kraken E4B 同级略低。</li><li>要比长上下文 prefill，用 <code>flm bench</code>，不要用短 chat 的 TTFT 反推。</li></ul>',27)])])}const y=e(i,[["render",n]]);export{c as __pageData,y as default};
